      "s.console.title": "Uygulama konsolu",
      "s.console.hint": "Uygulama konsolu bile\u015Feni i\xE7in uygulama ba\u015F\u0131na tu\u015Flar ve bir kadran: bile\u015Fen bu bilgisayarda \xF6ndeki uygulaman\u0131n tu\u015Flar\u0131n\u0131 g\xF6sterir ve onlar\u0131 yaln\u0131zca o uygulamaya g\xF6nderir. Uygulamalar, G\xF6rev Y\xF6neticisi\u2019nin Ayr\u0131nt\u0131lar sekmesindeki gibi i\u015Flem adlar\u0131d\u0131r (photoshop, gimp-2.10). Her sat\u0131ra bir tu\u015F, \xF6nce etiket sonra tu\u015Flar: Geri al = ctrl+z. Yaln\u0131zca Windows; tu\u015Flar bu bilgisayarda kal\u0131r.",
