      "s.photos.hint": "Foto\u011Fraf \xE7er\xE7evesi bile\u015Feni i\xE7in bu bilgisayardaki bir foto\u011Fraf klas\xF6r\xFC. E\u015Fitlenen bir OneDrive, Dropbox veya iCloud klas\xF6r\xFC de olur; yaln\u0131zca bulutta olan foto\u011Fraflar atlan\u0131r. Windows ve macOS'ta b\xFCy\xFCk foto\u011Fraflar telefona gitmeden \xF6nce burada k\xFC\xE7\xFClt\xFCl\xFCr ve yol bu bilgisayarda kal\u0131r.",
