      "s.pages.lead": "Her sayfa 12 \xD7 6 widget \u0131zgaras\u0131d\u0131r. Soldan bir sayfa se\xE7in, a\u015Fa\u011F\u0131daki telefonda widget'lar\u0131 yerle\u015Ftirin ve se\xE7eneklerini ayarlay\u0131n. Sayfalar\u0131 s\xFCr\xFCkleyerek s\u0131ralay\u0131n; ilki bo\u015Fta d\xF6n\xFClen ana sayfad\u0131r. Telefonda kayd\u0131r\u0131n, ses tu\u015Flar\u0131n\u0131 kullan\u0131n veya t\xFCm sayfalar\u0131 g\xF6rmek i\xE7in noktalara dokunun (ya da sayfaya bas\u0131l\u0131 tutun).",
      "s.pages.layout": "D\xFCzen",
      "s.pages.livePreview": "Canl\u0131 \xF6nizleme",
      "s.shortcuts.lead": "K\u0131sayol \u0131zgaras\u0131 ve B\xFCy\xFCk d\xFC\u011Fme widget'lar\u0131n\u0131n g\xF6sterdi\u011Fi tu\u015Flar. D\xFCzenlemek i\xE7in t\u0131klay\u0131n, s\u0131ralamak i\xE7in s\xFCr\xFCkleyin. Telefon yaln\u0131zca tu\u015F kimli\u011Fini g\xF6nderir; komutlar bu bilgisayardan d\u0131\u015Far\u0131 \xE7\u0131kmaz.",
      "s.rules.lead": 'Panelin bu bilgisayarda olanlara tepki vermesini sa\u011Flay\u0131n: Claude sizi bekledi\u011Finde AI sayfas\u0131n\u0131, m\xFCzik \xE7ald\u0131\u011F\u0131nda m\xFCzik sayfas\u0131n\u0131 veya arama s\u0131ras\u0131nda "yay\u0131nda" i\u015Faretini g\xF6sterin.',
