      "s.pages.lead": "Jede Seite ist ein 12 \xD7 6 Raster aus Widgets. W\xE4hlen Sie links eine Seite, ordnen Sie ihre Widgets unten auf dem Telefon an und legen Sie ihre Optionen fest. Ziehen Sie Seiten, um sie neu zu sortieren; die erste ist die Startseite, zu der das Panel im Leerlauf zur\xFCckkehrt. Wischen Sie auf dem Telefon, nutzen Sie die Lautst\xE4rketasten oder tippen Sie auf die Punkte (oder halten Sie eine Seite gedr\xFCckt), um eine \xDCbersicht aller Seiten zu sehen.",
      "s.pages.layout": "Layout",
      "s.pages.livePreview": "Live-Vorschau",
      "s.shortcuts.lead": 'Die Tasten, die die Widgets \u201EShortcut grid" und \u201EBig button" anzeigen. Klicken Sie eine Taste zum Bearbeiten, ziehen Sie zum Umsortieren. Das Telefon sendet nur die Kennung der Taste; Befehle verlassen diesen Computer nie.',
      "s.rules.lead": 'Lassen Sie das Panel auf Geschehnisse auf diesem Computer reagieren: zeigen Sie die AI-Seite, wenn Claude Sie braucht, die Musikseite, wenn etwas spielt, ein \u201EOn Air"-Zeichen w\xE4hrend Anrufen. Eine Regel wird ausgel\xF6st, wenn ihre Bedingung beginnt; mit \u201Enur solange sie gilt" kehrt das Telefon zu seinem vorherigen Zustand zur\xFCck (und ein gesendeter Wert wird entfernt), wenn die Bedingung endet.',
