      "s.console.title": "Console d\u2019application",
      "s.console.hint": "Des touches et une molette pour le widget Console d\u2019application, par application : le widget affiche les touches de l\u2019application au premier plan sur cet ordinateur et ne les envoie qu\u2019\xE0 elle. Les applications sont des noms de processus, comme dans l\u2019onglet D\xE9tails du Gestionnaire des t\xE2ches (photoshop, gimp-2.10). Une touche par ligne, un libell\xE9 puis les touches : Annuler = ctrl+z. Windows uniquement ; les touches restent sur cet ordinateur.",
