      "s.feeds.hint": "Flux RSS ou Atom pour le widget Flux d'actualit\xE9s. Cet ordinateur r\xE9cup\xE8re chacun au plus toutes les 15 minutes, seulement quand une page affiche un widget Flux d'actualit\xE9s ; les adresses restent ici.",
      "s.camera.title": "Cam\xE9ras",
      "s.camera.hint": "Cam\xE9ras IP pour le widget Cam\xE9ra : un nom et l\u2019adresse RTSP de la cam\xE9ra (rtsp://utilisateur:motdepasse@adresse:554/\u2026, dans sa notice ou son appli). Cet ordinateur ne r\xE9cup\xE8re une cam\xE9ra avec ffmpeg que pendant qu\u2019un widget Cam\xE9ra l\u2019affiche, et envoie au t\xE9l\xE9phone quelques images par seconde. Les adresses restent sur cet ordinateur, mais pendant qu\u2019une cam\xE9ra tourne elles sont visibles dans sa liste de processus.",
