      "s.pages.lead": "Chaque page est une grille 12 \xD7 6 de widgets. Choisissez une page \xE0 gauche, disposez ses widgets sur le t\xE9l\xE9phone ci-dessous et r\xE9glez leurs options. Faites glisser les pages pour les r\xE9ordonner ; la premi\xE8re est la page d'accueil vers laquelle le panneau revient au repos. Sur le t\xE9l\xE9phone, balayez, utilisez les touches de volume ou touchez les points (ou maintenez une page) pour avoir une vue de toutes les pages.",
      "s.pages.layout": "Disposition",
      "s.pages.livePreview": "Aper\xE7u en direct",
      "s.shortcuts.lead": "Les touches affich\xE9es par les widgets \xAB Shortcut grid \xBB et \xAB Big button \xBB. Cliquez sur une touche pour la modifier, faites-la glisser pour la r\xE9ordonner. Le t\xE9l\xE9phone n'envoie que l'identifiant de la touche ; les commandes ne quittent jamais cet ordinateur.",
      "s.rules.lead": "Laissez le panneau r\xE9agir \xE0 ce qui se passe sur cet ordinateur : affichez la page AI quand Claude a besoin de vous, la page musique quand quelque chose joue, un panneau \xAB \xE0 l'antenne \xBB pendant les appels. Une r\xE8gle se d\xE9clenche quand sa condition commence ; avec \xAB seulement tant qu'elle dure \xBB, le t\xE9l\xE9phone revient l\xE0 o\xF9 il \xE9tait (et une valeur pouss\xE9e est retir\xE9e) quand la condition se termine.",
