      "s.nav.advanced": "Avanzado",
      "s.pages.lead": "Cada p\xE1gina es una cuadr\xEDcula de 12 \xD7 6 widgets. Elige una p\xE1gina a la izquierda, organiza sus widgets en el tel\xE9fono de abajo y ajusta sus opciones. Arrastra las p\xE1ginas para reordenarlas; la primera es la p\xE1gina de inicio a la que vuelve el panel en reposo. En el tel\xE9fono, desliza, usa los botones de volumen o toca los puntos (o mant\xE9n pulsada una p\xE1gina) para ver todas las p\xE1ginas.",
      "s.pages.layout": "Dise\xF1o",
      "s.pages.livePreview": "Vista previa",
      "s.shortcuts.lead": "Las teclas que muestran los widgets \xABShortcut grid\xBB y \xABBig button\xBB. Haz clic en una tecla para editarla, arr\xE1strala para reordenar. El tel\xE9fono solo env\xEDa el id de la tecla; los comandos nunca salen de este ordenador.",
      "s.rules.lead": "Deja que el panel reaccione a lo que pasa en este ordenador: muestra la p\xE1gina de AI cuando Claude te necesita, la p\xE1gina de m\xFAsica cuando algo suena, un cartel de \xABen el aire\xBB durante las llamadas. Una regla se activa cuando empieza su condici\xF3n; con \xABsolo mientras dure\xBB el tel\xE9fono vuelve a donde estaba (y un valor enviado se retira) cuando la condici\xF3n termina.",
      "s.rules.add": "A\xF1adir regla",
