      "s.pages.lead": "Ogni pagina \xE8 una griglia 12 \xD7 6 di widget. Scegli una pagina a sinistra, disponi i suoi widget sul telefono qui sotto e imposta le loro opzioni. Trascina le pagine per riordinarle; la prima \xE8 la home a cui il pannello torna da inattivo. Sul telefono scorri, usa i tasti del volume o tocca i punti (o tieni premuta una pagina) per vedere tutte le pagine.",
      "s.pages.layout": "Layout",
      "s.pages.livePreview": "Anteprima live",
      "s.shortcuts.lead": "I tasti mostrati dai widget \xABShortcut grid\xBB e \xABBig button\xBB. Fai clic su un tasto per modificarlo, trascinalo per riordinare. Il telefono invia solo l'id del tasto; i comandi non escono mai da questo computer.",
      "s.rules.lead": "Lascia che il pannello reagisca a ci\xF2 che accade su questo computer: mostra la pagina AI quando Claude ha bisogno di te, la pagina musica quando qualcosa \xE8 in riproduzione, un cartello \xABon air\xBB durante le chiamate. Una regola scatta quando la sua condizione inizia; con \xABsolo finch\xE9 dura\xBB il telefono torna dov'era (e un valore inviato viene rimosso) quando la condizione finisce.",
      "s.rules.add": "Aggiungi regola",
