      "s.pages.lead": "Cada p\xE1gina \xE9 uma grelha de 12 \xD7 6 widgets. Escolha uma p\xE1gina \xE0 esquerda, organize os seus widgets no telem\xF3vel abaixo e defina as suas op\xE7\xF5es. Arraste as p\xE1ginas para as reordenar; a primeira \xE9 a p\xE1gina inicial para onde o painel volta quando est\xE1 parado. No telem\xF3vel, deslize, use as teclas de volume ou toque nos pontos (ou mantenha uma p\xE1gina premida) para ver todas as p\xE1ginas.",
      "s.pages.layout": "Disposi\xE7\xE3o",
      "s.pages.livePreview": "Pr\xE9-visualiza\xE7\xE3o",
      "s.shortcuts.lead": "As teclas mostradas pelos widgets \xABShortcut grid\xBB e \xABBig button\xBB. Clique numa tecla para a editar, arraste para reordenar. O telem\xF3vel envia apenas o id da tecla; os comandos nunca saem deste computador.",
      "s.rules.lead": "Deixe o painel reagir ao que acontece neste computador: mostre a p\xE1gina de AI quando o Claude precisar de si, a p\xE1gina de m\xFAsica quando algo tocar, um aviso \xABno ar\xBB durante chamadas. Uma regra dispara quando a sua condi\xE7\xE3o come\xE7a; com \xABs\xF3 enquanto durar\xBB o telem\xF3vel volta aonde estava (e um valor enviado \xE9 removido) quando a condi\xE7\xE3o termina.",
