      "s.pages.lead": "Elke pagina is een raster van 12 \xD7 6 widgets. Kies links een pagina, rangschik haar widgets op de telefoon hieronder en stel hun opties in. Sleep pagina's om ze te herschikken; de eerste is de homepagina waarheen het paneel bij inactiviteit terugkeert. Veeg op de telefoon, gebruik de volumetoetsen of tik op de puntjes (of houd een pagina ingedrukt) voor een overzicht van alle pagina's.",
      "s.pages.layout": "Indeling",
      "s.pages.livePreview": "Live voorbeeld",
      "s.shortcuts.lead": 'De toetsen die de widgets \u201EShortcut grid" en \u201EBig button" tonen. Klik op een toets om die te bewerken, sleep om te herschikken. De telefoon stuurt alleen de id van de toets; opdrachten verlaten deze computer nooit.',
      "s.rules.lead": 'Laat het paneel reageren op wat er op deze computer gebeurt: toon de AI-pagina wanneer Claude je nodig heeft, de muziekpagina wanneer er iets speelt, een \u201Eon air"-bord tijdens gesprekken. Een regel gaat af wanneer zijn voorwaarde begint; met \u201Ealleen zolang het duurt" gaat de telefoon terug naar waar hij was (en wordt een verzonden waarde verwijderd) wanneer de voorwaarde eindigt.',
