      "s.camera.title": "Kamery",
      "s.camera.hint": "Kamery IP dla wid\u017Cetu Kamera: nazwa i adres RTSP kamery (rtsp://u\u017Cytkownik:has\u0142o@adres:554/\u2026, z instrukcji lub aplikacji). Ten komputer pobiera obraz z kamery przez ffmpeg tylko wtedy, gdy pokazuje j\u0105 wid\u017Cet Kamera, i wysy\u0142a na telefon kilka klatek na sekund\u0119. Adresy zostaj\u0105 na tym komputerze, ale gdy kamera dzia\u0142a, s\u0105 widoczne na li\u015Bcie proces\xF3w.",
