      "s.pages.lead": "Ka\u017Cda strona to siatka 12 \xD7 6 wid\u017Cet\xF3w. Wybierz stron\u0119 po lewej, rozmie\u015B\u0107 jej wid\u017Cety na telefonie poni\u017Cej i ustaw ich opcje. Przeci\u0105gnij strony, by zmieni\u0107 ich kolejno\u015B\u0107; pierwsza jest stron\u0105 g\u0142\xF3wn\u0105, do kt\xF3rej panel wraca po bezczynno\u015Bci. Na telefonie przesu\u0144 palcem, u\u017Cyj klawiszy g\u0142o\u015Bno\u015Bci lub dotknij kropek (albo przytrzymaj stron\u0119), by zobaczy\u0107 wszystkie strony.",
      "s.pages.layout": "Uk\u0142ad",
      "s.pages.livePreview": "Podgl\u0105d na \u017Cywo",
      "s.shortcuts.lead": 'Klawisze wy\u015Bwietlane przez wid\u017Cety \u201EShortcut grid" i \u201EBig button". Kliknij klawisz, by go edytowa\u0107, przeci\u0105gnij, by zmieni\u0107 kolejno\u015B\u0107. Telefon wysy\u0142a tylko identyfikator klawisza; polecenia nigdy nie opuszczaj\u0105 tego komputera.',
      "s.rules.lead": 'Pozw\xF3l panelowi reagowa\u0107 na to, co dzieje si\u0119 na tym komputerze: pokazuj stron\u0119 AI, gdy Claude ci\u0119 potrzebuje, stron\u0119 muzyki, gdy co\u015B gra, znak \u201Ena antenie" podczas rozm\xF3w. Regu\u0142a uruchamia si\u0119, gdy zaczyna jej warunek; z \u201Etylko p\xF3ki trwa" telefon wraca tam, gdzie by\u0142 (a wys\u0142ana warto\u015B\u0107 jest usuwana), gdy warunek si\u0119 ko\u0144czy.',
