      "panel.offlineHelp": "\u0410\u0433\u0435\u043D\u0442 PhoneBox \u0437\u0430\u043F\u0443\u0449\u0435\u043D? \u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 USB-\u043A\u0430\u0431\u0435\u043B\u044C \u0438\u043B\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0441\u043E\u043F\u0440\u044F\u0436\u0435\u043D\u0438\u0435 \u043F\u043E Wi-Fi \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043D\u0430 \u041F\u041A (Wi-Fi & Tailscale \u203A \u041F\u0440\u0438\u0432\u044F\u0437\u0430\u0442\u044C \u0442\u0435\u043B\u0435\u0444\u043E\u043D \u043F\u043E Wi-Fi) \u0438 \u043E\u0442\u0441\u043A\u0430\u043D\u0438\u0440\u0443\u0439\u0442\u0435 QR-\u043A\u043E\u0434.",
