      "s.discord.title": "Discord",
      "s.discord.enable": "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0430\u0442\u044C\u0441\u044F \u043A \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E Discord \u043D\u0430 \u044D\u0442\u043E\u043C \u041F\u041A (\u0434\u043B\u044F \u0432\u0438\u0434\u0436\u0435\u0442\u0430 Discord)",
      "s.discord.hint": "\u0421\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0430 discord.com/developers/applications, \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 OAuth2 \u0430\u0434\u0440\u0435\u0441 \u043F\u0435\u0440\u0435\u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F http://127.0.0.1 \u0438 \u0441\u043A\u043E\u043F\u0438\u0440\u0443\u0439\u0442\u0435 \u0441\u044E\u0434\u0430 \u0435\u0433\u043E Client ID \u0438 \u0441\u0435\u043A\u0440\u0435\u0442. Discord \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442 \u043E\u0434\u043E\u0431\u0440\u0438\u0442\u044C PhoneBox. \u0415\u0441\u043B\u0438 \u043E\u043D \u043E\u0442\u043A\u043B\u043E\u043D\u044F\u0435\u0442 \u0432\u0445\u043E\u0434, \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0441\u0432\u043E\u044E \u0443\u0447\u0451\u0442\u043D\u0443\u044E \u0437\u0430\u043F\u0438\u0441\u044C \u0432 App Testers \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F. \u041F\u043E\u0448\u0430\u0433\u043E\u0432\u043E: docs/DISCORD.md.",
      "s.discord.clientId": "Client ID",
