      "s.nav.rules": "\u041F\u0440\u0430\u0432\u0438\u043B\u0430",
      "s.nav.webhooks": "\u0412\u0435\u0431\u0445\u0443\u043A\u0438",
      "s.nav.general": "\u041E\u0431\u0449\u0438\u0435",
      "s.nav.advanced": "\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u043D\u044B\u0435",
      "s.pages.lead": "\u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u2014 \u0441\u0435\u0442\u043A\u0430 \u0432\u0438\u0434\u0436\u0435\u0442\u043E\u0432 12 \xD7 6. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0441\u043B\u0435\u0432\u0430, \u0440\u0430\u0437\u043C\u0435\u0441\u0442\u0438\u0442\u0435 \u0435\u0451 \u0432\u0438\u0434\u0436\u0435\u0442\u044B \u043D\u0430 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0435 \u043D\u0438\u0436\u0435 \u0438 \u0437\u0430\u0434\u0430\u0439\u0442\u0435 \u0438\u0445 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B. \u041F\u0435\u0440\u0435\u0442\u0430\u0449\u0438\u0442\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B, \u0447\u0442\u043E\u0431\u044B \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A; \u043F\u0435\u0440\u0432\u0430\u044F \u2014 \u0434\u043E\u043C\u0430\u0448\u043D\u044F\u044F, \u043A \u043D\u0435\u0439 \u043F\u0430\u043D\u0435\u043B\u044C \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u043E\u0441\u0442\u043E\u044F. \u041D\u0430 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0435 \u0441\u043C\u0430\u0445\u0438\u0432\u0430\u0439\u0442\u0435, \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 \u043A\u043E\u0441\u043D\u0438\u0442\u0435\u0441\u044C \u0442\u043E\u0447\u0435\u043A (\u043B\u0438\u0431\u043E \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443), \u0447\u0442\u043E\u0431\u044B \u0443\u0432\u0438\u0434\u0435\u0442\u044C \u0432\u0441\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B.",
      "s.pages.layout": "\u041C\u0430\u043A\u0435\u0442",
      "s.pages.livePreview": "\u041F\u0440\u0435\u0434\u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440",
      "s.shortcuts.lead": "\u041A\u043B\u0430\u0432\u0438\u0448\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u0432\u0438\u0434\u0436\u0435\u0442\u044B \xABShortcut grid\xBB \u0438 \xABBig button\xBB. \u0429\u0451\u043B\u043A\u043D\u0438\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0443 \u0434\u043B\u044F \u043F\u0440\u0430\u0432\u043A\u0438, \u043F\u0435\u0440\u0435\u0442\u0430\u0449\u0438\u0442\u0435 \u0434\u043B\u044F \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u043F\u043E\u0440\u044F\u0434\u043A\u0430. \u0422\u0435\u043B\u0435\u0444\u043E\u043D \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0442\u043E\u043B\u044C\u043A\u043E id \u043A\u043B\u0430\u0432\u0438\u0448\u0438; \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u043F\u043E\u043A\u0438\u0434\u0430\u044E\u0442 \u044D\u0442\u043E\u0442 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440.",
      "s.rules.lead": "\u041F\u0443\u0441\u0442\u044C \u043F\u0430\u043D\u0435\u043B\u044C \u0440\u0435\u0430\u0433\u0438\u0440\u0443\u0435\u0442 \u043D\u0430 \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u044F\u0449\u0435\u0435 \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435: \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 AI, \u043A\u043E\u0433\u0434\u0430 Claude \u043D\u0443\u0436\u0435\u043D, \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u043C\u0443\u0437\u044B\u043A\u0438, \u043A\u043E\u0433\u0434\u0430 \u0447\u0442\u043E-\u0442\u043E \u0438\u0433\u0440\u0430\u0435\u0442, \u0442\u0430\u0431\u043B\u0438\u0447\u043A\u0443 \xAB\u0432 \u044D\u0444\u0438\u0440\u0435\xBB \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0437\u0432\u043E\u043D\u043A\u043E\u0432. \u041F\u0440\u0430\u0432\u0438\u043B\u043E \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442, \u043A\u043E\u0433\u0434\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0435\u0433\u043E \u0443\u0441\u043B\u043E\u0432\u0438\u0435; \u0441 \xAB\u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u043A\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442\xBB \u0442\u0435\u043B\u0435\u0444\u043E\u043D \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u0442\u0443\u0434\u0430, \u0433\u0434\u0435 \u0431\u044B\u043B (\u0430 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043D\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0443\u0434\u0430\u043B\u044F\u0435\u0442\u0441\u044F), \u043A\u043E\u0433\u0434\u0430 \u0443\u0441\u043B\u043E\u0432\u0438\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F.",
      "s.rules.add": "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043F\u0440\u0430\u0432\u0438\u043B\u043E",
      "s.rules.pause1h": "\u041F\u0440\u0438\u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0432\u0441\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u043D\u0430 1 \u0447\u0430\u0441",
      "s.general.lead": "\u041F\u043E\u0433\u043E\u0434\u0430, \u043D\u043E\u0447\u043D\u043E\u0439 \u0440\u0435\u0436\u0438\u043C, \u044D\u043A\u0440\u0430\u043D \u0438 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430.",
