      "w.console.noProfile": "Kh\xF4ng c\xF3 ph\xEDm n\xE0o cho \u1EE9ng d\u1EE5ng \u1EDF ph\xEDa tr\u01B0\u1EDBc.\nTh\xEAm trong C\xE0i \u0111\u1EB7t \u203A Chung \u203A B\u1EA3ng \u0111i\u1EC1u khi\u1EC3n \u1EE9ng d\u1EE5ng",
