      "s.nav.general": "Chung",
      "s.nav.advanced": "N\xE2ng cao",
      "s.pages.lead": "M\u1ED7i trang l\xE0 m\u1ED9t l\u01B0\u1EDBi widget 12 \xD7 6. Ch\u1ECDn m\u1ED9t trang \u1EDF b\xEAn tr\xE1i, s\u1EAFp x\u1EBFp c\xE1c widget c\u1EE7a n\xF3 tr\xEAn chi\u1EBFc \u0111i\u1EC7n tho\u1EA1i b\xEAn d\u01B0\u1EDBi v\xE0 \u0111\u1EB7t t\xF9y ch\u1ECDn cho ch\xFAng. K\xE9o c\xE1c trang \u0111\u1EC3 s\u1EAFp x\u1EBFp l\u1EA1i; trang \u0111\u1EA7u ti\xEAn l\xE0 trang ch\u1EE7 m\xE0 b\u1EA3ng \u0111i\u1EC1u khi\u1EC3n quay v\u1EC1 khi kh\xF4ng ho\u1EA1t \u0111\u1ED9ng. Tr\xEAn \u0111i\u1EC7n tho\u1EA1i, vu\u1ED1t, d\xF9ng ph\xEDm \xE2m l\u01B0\u1EE3ng, ho\u1EB7c ch\u1EA1m v\xE0o c\xE1c ch\u1EA5m (ho\u1EB7c nh\u1EA5n gi\u1EEF m\u1ED9t trang) \u0111\u1EC3 xem t\u1ED5ng quan t\u1EA5t c\u1EA3 c\xE1c trang.",
      "s.pages.layout": "B\u1ED1 c\u1EE5c",
      "s.pages.livePreview": "Xem tr\u01B0\u1EDBc tr\u1EF1c ti\u1EBFp",
      "s.shortcuts.lead": "C\xE1c ph\xEDm \u0111\u01B0\u1EE3c hi\u1EC3n th\u1ECB b\u1EDFi widget L\u01B0\u1EDBi ph\xEDm t\u1EAFt v\xE0 N\xFAt l\u1EDBn. Nh\u1EA5p v\xE0o m\u1ED9t ph\xEDm \u0111\u1EC3 ch\u1EC9nh s\u1EEDa, k\xE9o \u0111\u1EC3 s\u1EAFp x\u1EBFp l\u1EA1i. \u0110i\u1EC7n tho\u1EA1i ch\u1EC9 g\u1EEDi id c\u1EE7a ph\xEDm; c\xE1c l\u1EC7nh kh\xF4ng bao gi\u1EDD r\u1EDDi kh\u1ECFi m\xE1y t\xEDnh n\xE0y.",
      "s.rules.lead": '\u0110\u1EC3 b\u1EA3ng \u0111i\u1EC1u khi\u1EC3n ph\u1EA3n \u1EE9ng v\u1EDBi nh\u1EEFng g\xEC x\u1EA3y ra tr\xEAn m\xE1y t\xEDnh n\xE0y: hi\u1EC7n trang AI khi Claude c\u1EA7n b\u1EA1n, trang nh\u1EA1c khi c\xF3 g\xEC \u0111\xF3 \u0111ang ph\xE1t, bi\u1EC3n b\xE1o "\u0111ang ph\xE1t s\xF3ng" trong c\xE1c cu\u1ED9c g\u1ECDi. M\u1ED9t quy t\u1EAFc k\xEDch ho\u1EA1t khi \u0111i\u1EC1u ki\u1EC7n c\u1EE7a n\xF3 b\u1EAFt \u0111\u1EA7u; v\u1EDBi t\xF9y ch\u1ECDn ch\u1EC9 trong l\xFAc \u0111i\u1EC1u ki\u1EC7n k\xE9o d\xE0i, \u0111i\u1EC7n tho\u1EA1i s\u1EBD quay l\u1EA1i n\u01A1i tr\u01B0\u1EDBc \u0111\xF3 (v\xE0 gi\xE1 tr\u1ECB \u0111\xE3 \u0111\u1EA9y s\u1EBD b\u1ECB x\xF3a) khi \u0111i\u1EC1u ki\u1EC7n k\u1EBFt th\xFAc.',
      "s.rules.add": "Th\xEAm quy t\u1EAFc",
      "s.rules.pause1h": "T\u1EA1m d\u1EEBng m\u1ECDi quy t\u1EAFc trong 1 gi\u1EDD",
